head.b:skin:
:root{--bg:#070b11;--panel:#0d141d;--panel2:#111b27;--line:#223247;--text:#eef8ff;--muted:#91a6ba;--cyan:#52e8ff;--blue:#72aaff;--violet:#b28cff;--hot:#ff557f;--green:#70f0b1;--amber:#ffc96b;--max:1380px;--r:18px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 10% 0,rgba(82,232,255,.09),transparent 34rem),radial-gradient(circle at 90% 5%,rgba(178,140,255,.08),transparent 30rem),var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif;line-height:1.62}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}.edge-shell{width:min(calc(100% - 34px),var(--max));margin:0 auto}.edge-topline{height:3px;background:linear-gradient(90deg,var(--cyan),var(--blue),var(--violet),var(--hot))}
.edge-head{position:sticky;top:0;z-index:50;background:rgba(7,11,17,.94);border-bottom:1px solid var(--line)}.edge-headrow{min-height:80px;display:flex;align-items:center;gap:24px}.edge-brand{font-size:38px;font-weight:900;letter-spacing:-2px}.edge-brand span{color:var(--cyan);text-shadow:0 0 22px rgba(82,232,255,.4)}.edge-tag{font-size:11px;color:var(--muted);letter-spacing:1.5px;text-transform:uppercase}.edge-search{margin-left:auto;display:flex;min-width:min(360px,36vw);border:1px solid var(--line);border-radius:999px;background:var(--panel);overflow:hidden}.edge-search input{width:100%;border:0;outline:0;background:transparent;color:var(--text);padding:12px 15px}.edge-search button{border:0;background:transparent;color:var(--cyan);font-weight:800;padding:10px 15px;cursor:pointer}.edge-nav{border-top:1px solid rgba(255,255,255,.04);overflow:auto}.edge-nav-inner{display:flex;min-width:max-content}.edge-nav a{padding:12px 13px;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#b8cada;border-bottom:2px solid transparent}.edge-nav a:hover{color:#fff;border-bottom-color:var(--cyan)}
.edge-ticker{background:#091018;border-bottom:1px solid var(--line)}.edge-ticker-inner{min-height:44px;display:flex;align-items:center;overflow:hidden}.ticker-label{flex:none;background:var(--cyan);color:#041017;font-size:10px;font-weight:900;letter-spacing:1.3px;padding:5px 9px;border-radius:6px;margin-right:16px}.ticker-window{overflow:hidden;white-space:nowrap;flex:1}.ticker-track{display:inline-flex;gap:34px;animation:edgeTicker 55s linear infinite}.ticker-track:hover{animation-play-state:paused}.ticker-item{font-size:13px;color:#d8e8f4}.ticker-item:before{content:'◆';font-size:7px;color:var(--violet);margin-right:8px}@keyframes edgeTicker{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.edge-hero-wrap{padding:26px 0 8px}.edge-kicker{font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:var(--cyan);margin-bottom:12px}.edge-hero{display:grid;grid-template-columns:1.55fr .85fr;gap:16px}.hero-main,.hero-side{display:grid;gap:16px}.hero-side{grid-template-rows:1fr 1fr}.hero-card{position:relative;min-height:220px;overflow:hidden;border:1px solid var(--line);border-radius:var(--r);background:linear-gradient(145deg,#13202d,#0b1118)}.hero-main .hero-card{min-height:470px}.hero-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.55}.hero-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(4,8,13,.98),rgba(4,8,13,.22))}.hero-copy{position:absolute;z-index:2;left:0;right:0;bottom:0;padding:28px}.hero-copy h2{font-size:clamp(27px,4vw,50px);line-height:1.05;letter-spacing:-1.7px;margin:9px 0 10px}.hero-side .hero-copy h2{font-size:clamp(19px,2vw,27px)}.hero-meta{font-size:10px;color:#b8cada;letter-spacing:1px;text-transform:uppercase}.hero-summary{color:#c7d5e0;font-size:14px;max-width:760px}.hero-side .hero-summary{display:none}.edge-chip{display:inline-block;border:1px solid rgba(82,232,255,.35);background:rgba(82,232,255,.09);color:var(--cyan);border-radius:999px;padding:4px 8px;font-size:9px;font-weight:800;letter-spacing:1px;text-transform:uppercase}.edge-empty{display:flex;align-items:flex-end;min-height:220px;padding:22px;color:var(--muted)}
.edge-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:28px;padding:28px 0 58px}.edge-title{display:flex;align-items:flex-end;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:10px;margin-bottom:18px}.edge-title h2{margin:0;font-size:23px;letter-spacing:-.7px}.edge-title span{font-size:10px;color:var(--muted);letter-spacing:1px;text-transform:uppercase}.main .widget,.Blog{background:transparent!important}.post-outer,.post-outer-container{background:var(--panel)!important;border:1px solid var(--line)!important;border-radius:var(--r)!important;margin:0 0 18px!important;overflow:hidden}.post{padding:25px!important}.post-title,.post-title.entry-title{font-size:clamp(25px,3vw,38px)!important;line-height:1.12!important;letter-spacing:-1px!important;margin:0 0 11px!important}.post-title a:hover{color:var(--cyan)}.post-header,.post-header-line-1,.post-timestamp{color:var(--muted)!important;font-size:12px!important}.post-body{font-size:16px;color:#d6e2eb}.post-body h2,.post-body h3{color:#f5fbff}.post-body a{color:var(--cyan);text-decoration:underline}.post-body blockquote{border-left:3px solid var(--violet);padding:8px 18px;margin:22px 0;background:rgba(178,140,255,.05);color:#c3d0dc}.post-labels a,.labels a{display:inline-block;margin:5px 5px 0 0;border:1px solid var(--line);border-radius:999px;padding:5px 9px;color:#bdcedc;font-size:10px;text-transform:uppercase;letter-spacing:.6px}.post-labels a[href*='CONFIRMED']{color:var(--green)}.post-labels a[href*='DEVELOPING']{color:var(--amber)}.post-labels a[href*='EARLY']{color:var(--blue)}.post-labels a[href*='RUMOUR']{color:var(--hot)}
.edge-side{display:flex;flex-direction:column;gap:18px}.edge-box{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:19px}.edge-box h3{margin:0 0 13px;font-size:13px;letter-spacing:1px;text-transform:uppercase}.edge-status{display:grid;grid-template-columns:1fr 1fr;gap:8px}.edge-status a,.edge-cats a{border:1px solid var(--line);border-radius:10px;padding:10px;font-size:11px;color:#c8d7e3}.edge-status b{display:block;color:var(--cyan);font-size:15px}.edge-list{display:flex;flex-direction:column}.edge-list a{padding:10px 0;border-top:1px solid rgba(255,255,255,.055);font-size:13px;font-weight:700;line-height:1.35}.edge-list a:first-child{border-top:0}.edge-list small{display:block;margin-top:4px;color:var(--muted);font-weight:400}.edge-cats{display:grid;grid-template-columns:1fr 1fr;gap:8px}.edge-about{font-size:13px;color:var(--muted)}
.edge-foot{border-top:1px solid var(--line);padding:34px 0 50px;color:var(--muted);font-size:12px}.edge-foot-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:28px}.edge-foot strong{color:#fff;font-size:15px}.edge-foot a:hover{color:var(--cyan)}
@media(max-width:960px){.edge-tag{display:none}.edge-search{min-width:0;flex:1}.edge-hero{grid-template-columns:1fr}.hero-main .hero-card{min-height:390px}.hero-side{grid-template-columns:1fr 1fr;grid-template-rows:auto}.edge-layout{grid-template-columns:1fr}.edge-side{display:grid;grid-template-columns:1fr 1fr}}
@media(max-width:640px){.edge-shell{width:min(calc(100% - 22px),var(--max))}.edge-headrow{min-height:68px;gap:10px}.edge-brand{font-size:27px}.edge-search input{padding:9px 10px}.edge-search button{padding:9px 10px}.hero-main .hero-card{min-height:350px}.hero-side{grid-template-columns:1fr}.hero-side .hero-card{min-height:205px}.hero-copy{padding:20px}.hero-copy h2{font-size:29px}.edge-layout{padding-top:20px}.edge-side{display:flex}.post{padding:19px!important}.edge-foot-grid{grid-template-columns:1fr}}

body.script:
//
(function(){
function esc(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML;}
function entries(j){return(j&&j.feed&&j.feed.entry)||[];}
function href(e){var a=(e.link||[]),i;for(i=0;i<a.length;i++){if(a[i].rel==='alternate')return a[i].href;}return'#';}
function thumb(e){if(e.media$thumbnail&&e.media$thumbnail.url)return e.media$thumbnail.url.replace(/\/s72-c\//,'/s1200/');var c=(e.content&&e.content.$t)||'',m=c.match(/<img[^>]+src=["']([^"']+)/i);return m?m[1]:'';}
function plain(e){var s=(e.summary&&e.summary.$t)||(e.content&&e.content.$t)||'',d=document.createElement('div');d.innerHTML=s;return(d.textContent||'').replace(/\s+/g,' ').trim().slice(0,210);}
function when(e){var v=(e.published&&e.published.$t)||'';try{return new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}catch(x){return'';}}
function card(e,small){var im=thumb(e);return'<a class="hero-card" href="'+esc(href(e))+'">'+(im?'<img alt="" src="'+esc(im)+'"/>':'')+'<div class="hero-copy"><span class="edge-chip">Featured</span><h2>'+esc(e.title.$t)+'</h2><div class="hero-meta">'+esc(when(e))+'</div>'+(small?'':'<p class="hero-summary">'+esc(plain(e))+'</p>')+'</div></a>';}
window.edgeAIHero=function(j){var es=entries(j),h=document.getElementById('edgeai-hero');if(!h)return;if(!es.length&&!window.edgeAIFallback){window.edgeAIFallback=true;var x=document.createElement('script');x.src='/feeds/posts/default?alt=json-in-script&max-results=3&callback=edgeAIHero';document.body.appendChild(x);return;}if(!es.length)return;var a='<div class="hero-main">'+card(es[0],false)+'</div><div class="hero-side">';for(var i=1;i<3;i++)a+=es[i]?card(es[i],true):'<div class="hero-card edge-empty">More intelligence incoming.</div>';h.innerHTML=a+'</div>';};
window.edgeAITicker=function(j){var es=entries(j),t=document.getElementById('edgeai-ticker');if(!t||!es.length)return;var a='';for(var i=0;i<es.length;i++)a+='<a class="ticker-item" href="'+esc(href(es[i]))+'">'+esc(es[i].title.$t)+'</a>';t.innerHTML=a+a;};
window.edgeAITrending=function(j){var es=entries(j),t=document.getElementById('edgeai-trending');if(!t)return;var a='';for(var i=0;i<Math.min(es.length,6);i++)a+='<a href="'+esc(href(es[i]))+'">'+esc(es[i].title.$t)+'<small>'+esc(when(es[i]))+'</small></a>';t.innerHTML=a||'<span class="edge-about">No stories yet.</span>';};
var t=document.createElement('script');t.src='/feeds/posts/default?alt=json-in-script&max-results=10&callback=edgeAITicker';document.body.appendChild(t);
var r=document.createElement('script');r.src='/feeds/posts/default?alt=json-in-script&max-results=6&callback=edgeAITrending';document.body.appendChild(r);
if(document.getElementById('edgeai-hero')){var h=document.createElement('script');h.src='/feeds/posts/default/-/Featured?alt=json-in-script&max-results=3&callback=edgeAIHero';document.body.appendChild(h);}
})();
//
